package com.vishnu.hotelassistant.service;
import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import software.amazon.awssdk.core.sync.RequestBody; import software.amazon.awssdk.services.s3.S3Client; import software.amazon.awssdk.services.s3.model.PutObjectRequest; import java.util.UUID;
@Service public class S3StorageService {private final S3Client s3; private final String bucket; public S3StorageService(S3Client s3,@Value("${aws.s3.bucket}")String bucket){this.s3=s3;this.bucket=bucket;} public String upload(MultipartFile file){try{String key="hotel/"+UUID.randomUUID()+"-"+file.getOriginalFilename();s3.putObject(PutObjectRequest.builder().bucket(bucket).key(key).contentType(file.getContentType()).build(),RequestBody.fromBytes(file.getBytes()));return "s3://"+bucket+"/"+key;}catch(Exception e){throw new IllegalStateException("S3 upload failed: "+e.getMessage(),e);}}}
